// Runs on the machine hosting the Cronsole backend.
// Anything printed here lands in the task's run history.
// A non-zero exit is recorded as a failed run.

const startedAt = new Date();
console.log(`Ran at ${startedAt.toISOString()}`);

// Replace this with the work.
// process.exit(1) to record a failure.

// Runs on the machine hosting the Cronsole backend, using the built-in tls module.
// A non-zero exit records a failed run, same as a check that fails.
const tls = require("tls");

const host = "{{host}}";
const port = Number("{{port}}");
const warnDays = Number("{{warnDays}}");

const socket = tls.connect({ host, port, servername: host, timeout: 10000 }, () => {
  const cert = socket.getPeerCertificate();
  socket.end();
  if (!cert || !cert.valid_to) {
    console.error("No certificate returned by " + host + ":" + port);
    process.exitCode = 1;
    return;
  }
  const expiresAt = new Date(cert.valid_to);
  const daysLeft = Math.floor((expiresAt.getTime() - Date.now()) / 86400000);
  console.log("Certificate for " + host + " expires " + expiresAt.toISOString() + " (" + daysLeft + " days left).");
  if (daysLeft < warnDays) {
    console.error("Fewer than " + warnDays + " days remain.");
    process.exitCode = 1;
  }
});

socket.on("error", (err) => {
  console.error("TLS connection to " + host + ":" + port + " failed: " + err.message);
  process.exitCode = 1;
});

socket.on("timeout", () => {
  console.error("TLS connection to " + host + ":" + port + " timed out.");
  socket.destroy();
  process.exitCode = 1;
});

# Runs on the machine hosting the Cronsole backend, which must be a Windows host.
# A non-zero exit records a failed run, which is what makes this an alert rather than a status log.

$pending = $false
if (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending") { $pending = $true }
if (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired") { $pending = $true }

if ($pending) {
  Write-Output "A reboot is pending."
  exit 1
} else {
  Write-Output "No reboot pending."
}

// Runs on the machine hosting the Cronsole backend, and needs the docker CLI
// on that machine’s PATH with permission to talk to the Docker daemon.
const { execSync } = require("child_process");

let unhealthy = [];
try {
  unhealthy = execSync("docker ps --filter health=unhealthy -q", { encoding: "utf8" })
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
} catch (err) {
  console.error("Could not list containers: " + err.message);
  process.exitCode = 1;
}

if (unhealthy.length === 0) {
  console.log("No unhealthy containers.");
} else {
  for (const id of unhealthy) {
    try {
      execSync("docker restart " + id);
      console.log("Restarted " + id);
    } catch (err) {
      console.error("Failed to restart " + id + ": " + err.message);
      process.exitCode = 1;
    }
  }
}

// Runs on the machine hosting the Cronsole backend. Anything printed here
// lands in the task’s run history; a non-zero exit records a failed run.
const http = require("http");
const https = require("https");

const url = "{{url}}";
const maxMs = Number("{{maxMs}}");
const client = url.startsWith("https:") ? https : http;
const startedAt = Date.now();

const req = client.get(url, (res) => {
  res.on("data", () => {});
  res.on("end", () => {
    const elapsedMs = Date.now() - startedAt;
    console.log(url + " responded " + res.statusCode + " in " + elapsedMs + "ms");
    if (elapsedMs > maxMs) {
      console.error("Response took " + elapsedMs + "ms, over the " + maxMs + "ms limit.");
      process.exitCode = 1;
    }
  });
});

req.on("error", (err) => {
  console.error("Request to " + url + " failed: " + err.message);
  process.exitCode = 1;
});

req.setTimeout(15000, () => {
  req.destroy(new Error("request timed out"));
});
